'use client'

import { createViewTransition } from './view-transition-core'
import './transitions.css'

/**
 * Spaces.
 *
 * The way macOS switches desktops. The two pages are one rigid strip with a
 * thin gap between them, and the strip slides across on a spring — fast out
 * of the gate, a long soft landing, no overshoot unless you ask for one. As
 * it starts to move both pages lift off the surface a little, take on rounded
 * corners and lean into the direction of travel, cast a shadow onto the
 * backdrop, and settle back down flat and square as they land. The incoming
 * page trails the outgoing one by a frame, so the gap between them breathes
 * open at launch and closes on landing. A soft light on the backdrop moves at
 * a fraction of their speed.
 *
 * Direction comes from where you are going. Give it the order of your routes
 * and a page further along slides in from the right, a page further back from
 * the left, as though they really were laid out in a row. Anything not in the
 * list uses `direction`.
 *
 * Zero dependencies: the browser runs it off the stylesheet. The only script
 * work is choosing the direction and writing the spring as a CSS linear()
 * easing before the snapshot is taken.
 *
 *   // app/layout.tsx
 *   <SpacesTransition routes={['/', '/work', '/about']}>{children}</SpacesTransition>
 */
export type SpacesOptions = {
  /** Your routes in order, left to right. Decides which way a navigation slides. */
  routes: string[]
  /** Which way the pages travel when the destination is not in `routes`. */
  direction: 'left' | 'right'
  /** Seconds the switch takes, landing included. */
  duration: number
  /** Divides the duration. Above 1 is faster. */
  speed: number
  /** Space between the two pages while they travel, in px. */
  gap: number
  /** How far the pages shrink while in flight, in percent. 0 keeps them flat on the surface. */
  lift: number
  /** How far short of the full distance the outgoing page travels, 0 to 1. Above 0 it is overtaken rather than carried, and the gap goes. */
  parallax: number
  /** Overshoot on landing, 0 to 0.4. 0 is critically damped, the way macOS does it. */
  bounce: number
  /** Corner radius the pages take on while lifted, in px. They square up as they land. */
  radius: number
  /** Degrees each page leans into the direction of travel while in flight. */
  bank: number
  /** Milliseconds the incoming page trails the outgoing one, so the gap breathes. */
  lag: number
  /** What shows in the gap and around the lifted pages. "custom" leaves --spaces-backdrop to you. */
  backdrop: 'dark' | 'light' | 'custom'
}

const DEFAULTS: SpacesOptions = {
  routes: [],
  direction: 'left',
  duration: 0.55,
  speed: 1,
  gap: 12,
  lift: 4,
  parallax: 0,
  bounce: 0,
  radius: 16,
  bank: 5,
  lag: 16,
  backdrop: 'dark',
}

/** Index of the route that owns a path: exact match first, else the longest prefix. */
function slot(routes: string[], path: string): number {
  let best = -1
  let bestLen = -1
  routes.forEach((r, i) => {
    const hit = path === r || (r !== '/' && path.startsWith(r.endsWith('/') ? r : r + '/'))
    if (hit && r.length > bestLen) {
      best = i
      bestLen = r.length
    }
  })
  return best
}

/**
 * A damped spring as a CSS linear() easing. Simulated rather than solved in
 * closed form so one function covers both the critically damped case and the
 * bouncy one. The stiffness is chosen so that, with no bounce, the strip has
 * covered 58% of the distance a fifth of the way in and is within half a
 * percent at the end, and it leaves with some initial velocity: a switch is a
 * flick, not a release from rest.
 */
function spring(bounce: number, samples = 48): string {
  const w = 7
  const zeta = Math.max(0.5, 1 - bounce)
  let x = -1
  let v = 0.5 * w
  const per = 100
  const steps = samples * per
  const dt = 1 / steps
  const pts: string[] = ['0']
  for (let i = 1; i <= steps; i++) {
    const a = -w * w * x - 2 * zeta * w * v
    v += a * dt
    x += v * dt
    if (i % per === 0) pts.push(i === steps ? '1' : (1 + x).toFixed(4))
  }
  return `linear(${pts.join(', ')})`
}

export const SpacesTransition = createViewTransition<SpacesOptions>({
  name: 'spaces',
  defaults: DEFAULTS,
  defs: null,
  duration: (o) => o.duration / o.speed,

  prepare: (o, nav) => {
    const root = document.documentElement
    const from = slot(o.routes, nav.from)
    const to = slot(o.routes, nav.to)
    const travel = from >= 0 && to >= 0 && from !== to ? (to > from ? 'left' : 'right') : o.direction

    root.style.setProperty('--spaces-dir', travel === 'left' ? '-1' : '1')
    root.style.setProperty('--spaces-gap', `${o.gap}px`)
    root.style.setProperty('--spaces-lift', String(1 - o.lift / 100))
    root.style.setProperty('--spaces-stay', String(1 - o.parallax))
    root.style.setProperty('--spaces-ease', spring(o.bounce))
    root.style.setProperty('--spaces-radius', `${o.radius}px`)
    root.style.setProperty('--spaces-bank', `${o.bank}deg`)
    root.style.setProperty('--spaces-lag', `${o.lag}ms`)
    for (const b of ['dark', 'light']) root.classList.toggle(`spaces-${b}`, b === o.backdrop)
  },
})

'use client'

import { useEffect, useRef, type ReactNode } from 'react'
import { useRouter } from 'next/navigation'

export type ViewTransitionConfig<O> = {
  /**
   * Scopes this transition's stylesheet. The core puts `vt-<name>` on the
   * document element for the duration of the navigation, so two installed
   * transitions cannot both claim ::view-transition-old(root) — and neither
   * restyles a view transition it did not start.
   */
  name: string
  /** Values a consumer may override as props. */
  defaults: O
  /**
   * Rendered once and kept mounted. Masks and filters the stylesheet refers to
   * live here — they must sit above the page, because a page unmounts during
   * the navigation and would take its own defs with it.
   */
  defs: ReactNode | ((options: O) => ReactNode)
  /** Runs once per navigation, before the snapshot is taken. `nav` says where from and where to. */
  prepare?: (options: O, nav: { from: string; to: string }) => void
  /**
   * Drives one frame. progress runs 0 to 1. Omit it when the stylesheet does
   * the animating — the core still holds the snapshot open for the duration.
   */
  paint?: (progress: number, options: O) => void
  /** Seconds the transition should last. */
  duration: (options: O) => number
}

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/** Left alone: new tab, modified click, downloads, external, and same-page hashes. */
const isPlainInternalLink = (a: HTMLAnchorElement, e: MouseEvent) => {
  if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return false
  if (a.target && a.target !== '_self') return false
  if (a.hasAttribute('download')) return false
  const url = new URL(a.href, location.href)
  if (url.origin !== location.origin) return false
  if (url.pathname === location.pathname && url.hash) return false
  return true
}

/**
 * Turns a View Transitions config into a drop-in provider.
 *
 *   // app/layout.tsx
 *   <FilmBurnTransition>{children}</FilmBurnTransition>
 *
 * Unlike an overlay transition, this one has the outgoing page and the incoming
 * page on screen at the same time — the browser snapshots the old one — so the
 * effect can cut through one to the other rather than covering and uncovering.
 *
 * Browsers without the API navigate normally. Nothing breaks; there is simply
 * no animation.
 */
export function createViewTransition<O extends object>(config: ViewTransitionConfig<O>) {
  return function Transition({
    children,
    ...overrides
  }: { children: ReactNode } & Partial<O>) {
    const router = useRouter()
    const options = { ...config.defaults, ...(overrides as Partial<O>) } as O
    const latest = useRef(options)
    latest.current = options

    useEffect(() => {
      const onClick = (e: MouseEvent) => {
        const a = (e.target as Element | null)?.closest?.('a')
        if (!a || !isPlainInternalLink(a, e)) return

        const href = a.getAttribute('href')
        if (!href) return

        if (!document.startViewTransition || prefersReducedMotion()) return

        e.preventDefault()
        const o = latest.current
        const seconds = config.duration(o)

        try {
          config.prepare?.(o, { from: location.pathname, to: new URL(href, location.href).pathname })
          config.paint?.(0, o)
        } catch (error) {
          console.error('[transition] prepare failed, navigating plainly', error)
          router.push(href)
          return
        }

        const root = document.documentElement
        root.classList.add(`vt-${config.name}`)
        root.style.setProperty('--vt-duration', `${seconds}s`)

        const transition = document.startViewTransition(() => {
          router.push(href)
        })

        const cleanup = () => root.classList.remove(`vt-${config.name}`)
        transition.finished.then(cleanup, cleanup)

        transition.ready
          .then(() => {
            // Holds the snapshot on screen. Without an animation of its own the
            // browser ends the transition on the next frame and the pseudo
            // elements vanish before anything has been drawn.
            document.documentElement.animate(
              { opacity: [1, 1] },
              { duration: seconds * 1000, pseudoElement: '::view-transition-old(root)' },
            )

            if (!config.paint) return

            const start = performance.now()
            const step = () => {
              const t = Math.min(1, (performance.now() - start) / (seconds * 1000))
              try {
                config.paint!(t, o)
              } catch (error) {
                console.error('[transition] paint failed', error)
                return
              }
              if (t < 1) requestAnimationFrame(step)
            }
            requestAnimationFrame(step)
          })
          .catch(() => {
            /* transition was skipped or superseded; the navigation still happened */
          })
      }

      document.addEventListener('click', onClick)
      return () => document.removeEventListener('click', onClick)
    }, [router])

    return (
      <>
        {children}
        {typeof config.defs === 'function' ? config.defs(options) : config.defs}
      </>
    )
  }
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

/*
 * inset:0 sizes to the layout viewport, which excludes the scrollbar — so the
 * overlay is centred on the area the reader actually sees. 100vw would include
 * the scrollbar and push the centre to the right of the content instead.
 */
.transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
}

/* ---------- crayon ---------- */

/*
 * Scoped to crayon rather than every svg in an overlay. As `.transition-overlay
 * svg` it outranked any single class a later transition could put on its own
 * svg, so it silently forced them all to full size — the zipper only escaped
 * because it sets its own width and height.
 */
.crayon svg {
  display: block;
  width: 100%;
  height: 100%;
}

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

.crayon {
  position: absolute;
  inset: 0;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

/* Hidden until the first leave phase measures the real path lengths. */
.crayon path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- zipper ---------- */

/*
 * Every colour in the artwork reads from these, so overriding them anywhere
 * above the transition recolours the whole zip. Set your own values, or put one
 * of the preset classes below on any ancestor.
 */
:root {
  --zip-metal-hi: #ffffff;
  --zip-metal: #d7d2c8;
  --zip-metal-mid: #8f887c;
  --zip-metal-lo: #4a453e;
  --zip-metal-edge: #211f1c;
  --zip-tape: #3d3d46;
  --zip-tape-lo: #26262c;
}

.zip-steel {
  --zip-metal-hi: #f8fbfe;
  --zip-metal: #c3ced8;
  --zip-metal-mid: #7c8894;
  --zip-metal-lo: #3f4750;
  --zip-metal-edge: #171b20;
  --zip-tape: #2b313a;
  --zip-tape-lo: #191d23;
}

.zip-brass {
  --zip-metal-hi: #fff8dd;
  --zip-metal: #eccb6f;
  --zip-metal-mid: #b8912f;
  --zip-metal-lo: #6b5115;
  --zip-metal-edge: #2b2107;
  --zip-tape: #3a3228;
  --zip-tape-lo: #231f18;
}

.zip-gunmetal {
  --zip-metal-hi: #c6ccd4;
  --zip-metal: #848b95;
  --zip-metal-mid: #4f555d;
  --zip-metal-lo: #2a2d33;
  --zip-metal-edge: #101216;
  --zip-tape: #1f2228;
  --zip-tape-lo: #121418;
}

.zip-copper {
  --zip-metal-hi: #ffe9d6;
  --zip-metal: #e2a179;
  --zip-metal-mid: #a95f37;
  --zip-metal-lo: #5d3018;
  --zip-metal-edge: #23110a;
  --zip-tape: #332822;
  --zip-tape-lo: #1d1714;
}

.zip-rig {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.zip-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
}

.zip-band {
  position: absolute;
  width: 100%;
  overflow: hidden;
}

.zip-band-art {
  position: absolute;
}

.zip-slider-layer {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  pointer-events: none;
}

.zip-fill {
  height: 100%;
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .zip-rig { display: none }
}

/* ---------- film burn ---------- */

/*
 * The fire is its own colour, not the pages'. The outgoing page is masked away
 * inside the burn front, the incoming page is masked to show only inside a
 * slightly smaller front, and this ramp sits behind both — so what you see in
 * the gap between them is the fire itself.
 *
 * The ramp is anchored to the band rather than the origin. Anchored to the
 * origin, the visible annulus samples the cold end of the gradient once the
 * front is halfway out, and the fire goes dull.
 */
:root,
.burn-ember {
  --burn-core: #fff4dc;
  --burn-hot: #ffb32e;
  --burn-mid: #d94a12;
  --burn-edge: #6b1806;
}

/* Magnesium burns brilliant white and almost colourless — the point of it is
   that there is no hue, so this stays neutral all the way down. */
.burn-magnesium {
  --burn-core: #ffffff;
  --burn-hot: #f6f7f8;
  --burn-mid: #a9aeb4;
  --burn-edge: #34383d;
}

.burn-cold {
  --burn-core: #ddf5ff;
  --burn-hot: #33c9ff;
  --burn-mid: #0a5fd4;
  --burn-edge: #04123f;
}

.burn-toxic {
  --burn-core: #f4ffd9;
  --burn-hot: #c6ff3d;
  --burn-mid: #46b81a;
  --burn-edge: #0d3a0a;
}

.vt-film-burn::view-transition-group(root) {
  animation: none;
  background:
    radial-gradient(
      circle at var(--burn-x, 50%) var(--burn-y, 50%),
      var(--burn-core) calc(var(--burn-cut, 0px) - var(--burn-band, 64px)),
      var(--burn-hot) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.68),
      var(--burn-mid) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.3),
      var(--burn-edge) var(--burn-cut, 0px),
      var(--burn-edge) 100%
    );
}

.vt-film-burn::view-transition-image-pair(root) {
  isolation: auto;
}

/* The browser stacks the incoming snapshot above the outgoing one, so the
   outgoing page has to be lifted for its mask to read as a hole rather than as
   nothing at all. */
.vt-film-burn::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 1;
  mask: url(#burn-mask-new);
  -webkit-mask: url(#burn-mask-new);
}

.vt-film-burn::view-transition-old(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 2;
  mask: url(#burn-mask-old);
  -webkit-mask: url(#burn-mask-old);
}

/* ---------- riser ---------- */

/*
 * Nothing here is driven from JavaScript. The outgoing page is pushed back and
 * dimmed, the incoming page is unmasked over it, and the browser runs both off
 * the stylesheet — which is why this one needs no dependencies at all.
 */
.vt-riser::view-transition-group(root) {
  animation: none;
}

.vt-riser::view-transition-image-pair(root) {
  isolation: auto;
}

/*
 * Origin at the arriving edge, not the centre. Scaling about the centre pulls
 * the outgoing page away from that edge, so it reads as sliding off rather than
 * settling behind. Anchored to the edge it recedes into the space the incoming
 * page is about to occupy, and stays visible above it the whole way.
 */
.vt-riser::view-transition-old(root) {
  animation: riser-recede var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 1;
  transform-origin: var(--riser-origin, 50% 0%);
}

/*
 * The incoming page slides in as a card rather than being clipped into view. A
 * clip reveal has no edge and casts nothing, so there is no cue that one page
 * is above the other — the shadow is what actually sells the layering.
 */
.vt-riser::view-transition-new(root) {
  animation: riser-arrive var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 2;
  box-shadow: var(--riser-shadow, 0 -24px 60px rgba(0, 0, 0, 0.45));
}

/* The tilt is what makes it read as depth rather than a shrink — the page
   leans away from you as it drops back. */
/*
 * Perspective distance matters as much as the angle. At 1400px a 6deg lean
 * narrows the far edge by about 6%, which reads as nothing at all; 900px and
 * 14deg takes it to 80%, which is unmistakably a page leaning away.
 */
@keyframes riser-recede {
  to {
    opacity: var(--riser-dim, 0.35);
    transform: perspective(var(--riser-perspective, 800px))
      translate3d(var(--riser-out-x, 0), var(--riser-out-y, -8vh), 0)
      rotateX(var(--riser-tilt-x, 18deg)) rotateY(var(--riser-tilt-y, 0deg))
      scale(var(--riser-depth, 0.82));
  }
}

@keyframes riser-arrive {
  from {
    transform: translate3d(var(--riser-in-x, 0), var(--riser-in-y, 100%), 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

/* The incoming page is unmasked from the edge it arrives at, and the outgoing
   page recedes the opposite way, so the two read as one movement. */
.riser-up {
  --riser-in-y: 100%;
  --riser-in-x: 0;
  --riser-shadow: 0 -24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 0%;
  --riser-out-y: calc(var(--riser-travel, 8vh) * -1);
  --riser-out-x: 0;
  --riser-tilt-x: var(--riser-tilt, 18deg);
  --riser-tilt-y: 0deg;
}

.riser-down {
  --riser-in-y: -100%;
  --riser-in-x: 0;
  --riser-shadow: 0 24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 100%;
  --riser-out-y: var(--riser-travel, 8vh);
  --riser-out-x: 0;
  --riser-tilt-x: calc(var(--riser-tilt, 18deg) * -1);
  --riser-tilt-y: 0deg;
}

.riser-left {
  --riser-in-y: 0;
  --riser-in-x: 100%;
  --riser-shadow: -24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 0% 50%;
  --riser-out-x: calc(var(--riser-travel-x, 8vw) * -1);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: calc(var(--riser-tilt, 18deg) * -1);
}

.riser-right {
  --riser-in-y: 0;
  --riser-in-x: -100%;
  --riser-shadow: 24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 100% 50%;
  --riser-out-x: var(--riser-travel-x, 8vw);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: var(--riser-tilt, 18deg);
}

@media (prefers-reduced-motion: reduce) {
  .vt-riser::view-transition-old(root),
  .vt-riser::view-transition-new(root) {
    animation: none;
  }
}

/* ---------- push ---------- */

/*
 * Both pages travel the same direction, the outgoing one slower, so it is
 * overtaken rather than shoved off. Nothing but a transform on each snapshot
 * and a brightness on the one being covered — no JavaScript touches a frame.
 */

:root {
  /* Material 3's emphasized curve: leaves quickly, arrives gently. */
  --push-ease: cubic-bezier(0.2, 0, 0, 1);
}

.vt-push::view-transition-group(root) {
  animation: none;
}

.vt-push::view-transition-image-pair(root) {
  isolation: auto;
}

.vt-push::view-transition-old(root) {
  animation: push-recede var(--vt-duration, 0.42s) var(--push-ease) both;
  mix-blend-mode: normal;
  z-index: 1;
}

.vt-push::view-transition-new(root) {
  animation: push-arrive var(--vt-duration, 0.42s) var(--push-ease) both;
  mix-blend-mode: normal;
  z-index: 2;
  /* Reads the seam between the two pages while they overlap. */
  box-shadow: var(--push-shadow, -18px 0 48px rgba(0, 0, 0, 0.34));
}

/*
 * brightness rather than opacity: the outgoing page has the incoming one
 * already rendered behind it, so fading it out would cross-dissolve the two
 * instead of darkening one.
 */
@keyframes push-recede {
  to {
    transform: translate3d(var(--push-out-x, 0), var(--push-out-y, 0), 0);
    filter: brightness(var(--push-dim, 0.78));
  }
}

@keyframes push-arrive {
  from {
    transform: translate3d(var(--push-in-x, 100%), var(--push-in-y, 0), 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

.push-left {
  --push-in-x: 100%;
  --push-in-y: 0;
  --push-out-x: calc(var(--push-parallax, 28%) * -1);
  --push-out-y: 0;
  --push-shadow: -18px 0 48px rgba(0, 0, 0, 0.34);
}

.push-right {
  --push-in-x: -100%;
  --push-in-y: 0;
  --push-out-x: var(--push-parallax, 28%);
  --push-out-y: 0;
  --push-shadow: 18px 0 48px rgba(0, 0, 0, 0.34);
}

.push-up {
  --push-in-x: 0;
  --push-in-y: 100%;
  --push-out-x: 0;
  --push-out-y: calc(var(--push-parallax, 28%) * -1);
  --push-shadow: 0 -18px 48px rgba(0, 0, 0, 0.34);
}

.push-down {
  --push-in-x: 0;
  --push-in-y: -100%;
  --push-out-x: 0;
  --push-out-y: var(--push-parallax, 28%);
  --push-shadow: 0 18px 48px rgba(0, 0, 0, 0.34);
}

@media (prefers-reduced-motion: reduce) {
  .vt-push::view-transition-old(root),
  .vt-push::view-transition-new(root) {
    animation: none;
  }
}

/* ---------- concertina ---------- */

/*
 * The slats are laid out at their collapsed size and scaled up to cover, so
 * nothing here animates width or height — a strip of forty slats re-laying out
 * every frame is the one thing that would make this expensive.
 */

:root {
  --cc-ground: #0d0d0f;
  --cc-slat: #f6f4ef;
}

.cc-stage {
  position: absolute;
  inset: 0;
  overflow: clip;
}

.cc-ground {
  position: absolute;
  inset: 0;
  background: var(--cc-ground);
}

/*
 * The row runs in a centred window rather than edge to edge. Two things follow
 * from that: slats clip in and out at its sides as the row slides, and the arcs
 * span the window too — the same curve across a narrower span is much steeper
 * at its ends, which is what slants the outermost slats.
 */
.cc-window {
  position: absolute;
  top: 0;
  bottom: 0;
  /* left and width are set in whole pixels from the component — see sizeWindow. */
  left: 0;
  width: var(--cc-window, 60vw);
  overflow: hidden;
}

.cc-strip {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cc-slat {
  flex: 0 0 auto;
  /* So the one standing in for the page can be raised over its neighbours. */
  position: relative;
  width: var(--cc-slat-w, 3vw);
  height: var(--cc-slat-h, 45vh);
  margin: 0 var(--cc-gap, 0.5vw);
  background: var(--cc-slat);
}

/*
 * The bow. Two arcs in the ground colour lying over a row of flat slats — the
 * edge slats read as taller than the middle ones because each is bitten into by
 * a different part of the curve. preserveAspectRatio is none on purpose: a
 * quadratic stays a quadratic under a non-uniform scale, so the arc survives any
 * viewport shape and `bow` alone decides how deep it goes.
 */
.cc-arc {
  position: absolute;
  left: 0;
  width: 100%;
  height: 50%;
  display: block;
  fill: var(--cc-ground);
}

.cc-arc.is-top {
  top: 0;
}

.cc-arc.is-bottom {
  bottom: 0;
}

.cc-mono {
  --cc-ground: #0d0d0f;
  --cc-slat: #f6f4ef;
}

.cc-inverse {
  --cc-ground: #f2efe8;
  --cc-slat: #17171a;
}

.cc-ember {
  --cc-ground: #170a04;
  --cc-slat: #ff9d3c;
}

.cc-pine {
  --cc-ground: #0b1a16;
  --cc-slat: #7fd0b4;
}

/* ---------- dither ---------- */

:root {
  --dither-ground: #0a0a0a;
}

.dither {
  position: absolute;
  inset: 0;
  overflow: clip;
}

/* Scoped to its own canvas — see the note on `.crayon svg`. */
.dither canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.dither-ink       { --dither-ground: #0a0a0a; }
.dither-paper     { --dither-ground: #f2efe8; }
.dither-blueprint { --dither-ground: #1f4470; }
.dither-ember     { --dither-ground: #170a04; }

/* ---------- slate ---------- */

/*
 * Three pieces and nothing but transforms: the rig rises and is pulled out,
 * the stick rotates on its hinge, the board just rides along. The board
 * overruns the bottom so the rise's overshoot never shows an edge.
 */

:root {
  --slate-board: #141414;
  --slate-stripe: #f2efe8;
  --slate-stick: 12vh;
}

.slate {
  position: absolute;
  inset: 0;
  overflow: clip;
}

.slate-rig {
  position: absolute;
  inset: 0;
  will-change: transform;
}

.slate-stick {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: var(--slate-stick);
  transform-origin: 0% 100%;
  will-change: transform;
  /* Lies on the board when shut; hangs over it when open. */
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4);
}

/* A highlight along the top and a dark under-edge: a bar with thickness, not a painted band. */
.slate-stick::before,
.slate-stick::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
}

.slate-stick::before {
  top: 0;
  height: 2px;
  background: rgba(255, 255, 255, 0.28);
}

.slate-stick::after {
  bottom: 0;
  height: 3px;
  background: rgba(0, 0, 0, 0.4);
}

.slate-hinge-right .slate-stick {
  transform-origin: 100% 100%;
}

.slate-board {
  position: absolute;
  left: 0;
  right: 0;
  top: var(--slate-stick);
  bottom: -30vh;
  background: var(--slate-board);
  /* The board sits above the page: a shadow into the gap, and one all round
     for while it is off-square on the way in and out. */
  box-shadow:
    0 -6px 24px rgba(0, 0, 0, 0.35),
    0 0 60px rgba(0, 0, 0, 0.3);
}

.slate-lip {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: var(--slate-stick);
}

/* Stripes lean opposite ways on the two halves, meeting as chevrons at the seam. */
.slate-stick {
  background: repeating-linear-gradient(
    -60deg,
    var(--slate-stripe) 0 calc(var(--slate-stick) * 0.5),
    var(--slate-board) 0 calc(var(--slate-stick) * 1)
  );
}

.slate-lip {
  background: repeating-linear-gradient(
    60deg,
    var(--slate-stripe) 0 calc(var(--slate-stick) * 0.5),
    var(--slate-board) 0 calc(var(--slate-stick) * 1)
  );
}

.slate-ink   { --slate-board: #141414; --slate-stripe: #f2efe8; }
.slate-chalk { --slate-board: #f2efe8; --slate-stripe: #141414; }

@media (prefers-reduced-motion: reduce) {
  .slate { display: none }
}


/* ---------- spaces ---------- */

/*
 * Two snapshots as one strip. Nothing here is driven per frame: the direction,
 * the gap, the lift, the spring curve and the rest are written as custom
 * properties once before the snapshot, and the browser runs the keyframes off
 * them. The slide lives on `translate` and the bank on `transform`, so each
 * page leans about its own centre and is then carried across as a whole.
 */

:root,
.spaces-dark {
  --spaces-backdrop: #0d0d10;
  --spaces-glow: rgba(255, 255, 255, 0.12);
}

.spaces-light {
  --spaces-backdrop: #e8e5de;
  --spaces-glow: rgba(0, 0, 0, 0.08);
}

/*
 * The gap and the lifted edges show this, not the live page underneath. A soft
 * light on it slides the same way as the strip at a fraction of the speed, so
 * the gap has something behind it.
 */
.vt-spaces::view-transition {
  background-color: var(--spaces-backdrop);
  background-image: radial-gradient(45% 70% at 50% 45%, var(--spaces-glow), transparent 70%);
  background-size: 200% 100%;
  background-repeat: no-repeat;
  animation: spaces-light var(--vt-duration, 0.55s) var(--spaces-ease, cubic-bezier(0.2, 0, 0, 1)) both;
}

/* The lift lives on the group, so both pages shrink about the same centre. */
.vt-spaces::view-transition-group(root) {
  animation: spaces-lift var(--vt-duration, 0.55s) ease-in-out both;
}

.vt-spaces::view-transition-image-pair(root) {
  isolation: auto;
}

.vt-spaces::view-transition-old(root),
.vt-spaces::view-transition-new(root) {
  mix-blend-mode: normal;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.45);
}

/*
 * --spaces-stay is 1 minus the parallax. At 1 the outgoing page travels the
 * full distance and the two are one rigid strip; below that it lags, and the
 * incoming page, stacked above, overtakes it.
 */
.vt-spaces::view-transition-old(root) {
  animation:
    spaces-out var(--vt-duration, 0.55s) var(--spaces-ease, cubic-bezier(0.2, 0, 0, 1)) both,
    spaces-card var(--vt-duration, 0.55s) ease-in-out both,
    spaces-bank var(--vt-duration, 0.55s) ease-in-out both;
  z-index: 1;
}

/* The incoming page starts a frame late, so the gap opens at launch and closes on landing. */
.vt-spaces::view-transition-new(root) {
  animation:
    spaces-in var(--vt-duration, 0.55s) var(--spaces-ease, cubic-bezier(0.2, 0, 0, 1)) both,
    spaces-card var(--vt-duration, 0.55s) ease-in-out both,
    spaces-bank var(--vt-duration, 0.55s) ease-in-out both;
  animation-delay: var(--spaces-lag, 16ms), var(--spaces-lag, 16ms), var(--spaces-lag, 16ms);
  z-index: 2;
}

@keyframes spaces-out {
  to {
    translate: calc(var(--spaces-dir, -1) * (100% + var(--spaces-gap, 12px)) * var(--spaces-stay, 1)) 0;
  }
}

@keyframes spaces-in {
  from {
    translate: calc(-1 * var(--spaces-dir, -1) * (100% + var(--spaces-gap, 12px))) 0;
  }
  to {
    translate: 0 0;
  }
}

/* Off the surface quickly, carried, and set back down as the strip lands. */
@keyframes spaces-lift {
  0%   { transform: scale(1); }
  18%  { transform: scale(var(--spaces-lift, 0.96)); }
  55%  { transform: scale(var(--spaces-lift, 0.96)); }
  100% { transform: scale(1); }
}

/* Cards while in flight, sheets once landed. */
@keyframes spaces-card {
  0%, 100% { border-radius: 0; }
  18%, 55% { border-radius: var(--spaces-radius, 16px); }
}

/* Each page leans into the direction of travel about its own centre: the trailing edge comes forward, like a card flicked across a table. */
@keyframes spaces-bank {
  0%, 100% { transform: perspective(1200px) rotateY(0deg); }
  18%, 55% { transform: perspective(1200px) rotateY(calc(var(--spaces-dir, -1) * var(--spaces-bank, 5deg))); }
}

@keyframes spaces-light {
  from { background-position-x: calc(50% + var(--spaces-dir, -1) * 15%); }
  to   { background-position-x: calc(50% - var(--spaces-dir, -1) * 15%); }
}

@media (prefers-reduced-motion: reduce) {
  .vt-spaces::view-transition,
  .vt-spaces::view-transition-group(root),
  .vt-spaces::view-transition-old(root),
  .vt-spaces::view-transition-new(root) {
    animation: none;
  }
}
